#!/usr/bin/env bash
# ONE sudoers artifact, regenerated by the committed route: gunbc.instruments.generated_artifact_gate
# main_wet_one <path>, which is main_wet's own roster projected to the one path asked for (never a second
# roster -- see the comment above main_wet_one). Nothing here composes a sudoers line; the emitter does.
#
# ONE PATH PER DISPATCH, DELIBERATELY. main_wet_one pays the whole-tree resolve every process (~20 min of
# the 45-min runner cap, measured 2026-11-10), and the resolve is not shared between processes, so four
# paths in one script cannot finish inside the cap. Four dispatches, one path each, in parallel.
#
# Usage: bash tools/runner_sudoers_regen_dispatch.sh provisioning/srv3/gunbc-ghrunner.sudoers
set -uo pipefail
PATH_ARG="${1:?usage: $0 <committed artifact path, e.g. provisioning/srv3/gunbc-ghrunner.sudoers>}"
case "$PATH_ARG" in
  provisioning/srv*/gunbc-ghrunner.sudoers) ;;
  *) echo "refusing: $0 regenerates a runner sudoers artifact and nothing else"; exit 2 ;;
esac

cd "$(dirname "$0")/.." || { echo "no worktree"; exit 2; }
LOG=/tmp/runner_sudoers_regen_one.out
: > "$LOG"

echo "== cargo build (claim_batch's compiler) =="
cargo build --release -p v1-compiler --bin gunbc >>"$LOG" 2>&1
echo "BUILD_RC=$?"
BIN=./target/release/gunbc

echo "== main_wet_one $PATH_ARG =="
start=$(date +%s)
timeout 1700 "$BIN" run --source-root dag --source-root src/v1 --source-root src/v2 \
  --entry dag/gunbc/instruments/generated_artifact_gate.dag --function main_wet_one \
  --arg path="$PATH_ARG" >>"$LOG" 2>&1
echo "MAIN_WET_RC=$? ELAPSED=$(( $(date +%s) - start ))s"

# Everything the run said comes back on stdout: ctrl-build only streams stdout, so a log left in the
# runner's /tmp is a log that never happened.
echo "== FULL RUNNER LOG =="
cat "$LOG"

echo "== activation-line accounting in the rendered bytes =="
for h in srv1 srv2 srv3 srv4; do
  f="provisioning/$h/gunbc-ghrunner.sudoers"
  printf "%s lines=%s unmask=%s enable=%s start=%s masknow=%s stop=%s\n" "$h" \
    "$(grep -c '' "$f")" \
    "$(grep -c 'systemctl unmask ' "$f")" \
    "$(grep -c 'systemctl enable ' "$f")" \
    "$(grep -c 'systemctl start ' "$f")" \
    "$(grep -c 'systemctl mask --now ' "$f")" \
    "$(grep -c 'systemctl stop ' "$f")"
done

# The sudoers comes back as a patch, not as a whole file: the fold ADDS the activation rows it was missing,
# and a review is line by line.
echo "== PATCH-BEGIN =="
git diff -- "$PATH_ARG"
echo "== PATCH-END =="
echo "REGEN DISPATCH DONE"
